func (fx *TensorboardServiceTensorboardTimeSeriesTestSuiteConfig) nextParent(t *testing.T, pristine bool) string {
	if pristine {
		fx.currParent++
	}
	if fx.currParent >= len(fx.Parents) {
		t.Fatal("need at least", fx.currParent+1, "parents")
	}
	return fx.Parents[fx.currParent]
}

func (fx *TensorboardServiceTensorboardTimeSeriesTestSuiteConfig) peekNextParent(t *testing.T) string {
	next := fx.currParent + 1
	if next >= len(fx.Parents) {
		t.Fatal("need at least", next+1, "parents")
	}
	return fx.Parents[next]
}

func (fx *TensorboardServiceTensorboardTimeSeriesTestSuiteConfig) maybeSkip(t *testing.T) {
	for _, skip := range fx.Skip {
		if strings.Contains(t.Name(), skip) {
			t.Skip("skipped because of .Skip")
		}
	}
}

func (fx *TensorboardServiceTensorboardTimeSeriesTestSuiteConfig) normalize(msg *TensorboardTimeSeries) *TensorboardTimeSeries {
	if fx.Normalize == nil || msg == nil {
		return msg
	}
	normalized := proto.Clone(msg).(*TensorboardTimeSeries)
	fx.Normalize(normalized)
	return normalized
}

func (fx *TensorboardServiceTensorboardTimeSeriesTestSuiteConfig) normalizeAll(msgs []*TensorboardTimeSeries) []*TensorboardTimeSeries {
	if fx.Normalize == nil {
		return msgs
	}
	normalized := make([]*TensorboardTimeSeries, len(msgs))
	for i, msg := range msgs {
		normalized[i] = fx.normalize(msg)
	}
	return normalized
}

func (fx *TensorboardServiceTensorboardTimeSeriesTestSuiteConfig) listed(t *testing.T, parent string, want, got []*TensorboardTimeSeries) []*TensorboardTimeSeries {
	t.Helper()
	assert.Equal(t, len(want)+fx.Preexisting, len(got), "listed resources, with Preexisting")
	names := make(map[string]bool, len(want))
	for _, msg := range want {
		names[msg.Name] = true
	}
	created := make([]*TensorboardTimeSeries, 0, len(want))
	for _, msg := range got {
		assert.Check(t, strings.HasPrefix(msg.Name, parent+"/"), "listed resource is not under the parent")
		if names[msg.Name] {
			created = append(created, msg)
		}
	}
	return created
}

func (fx *TensorboardServiceTensorboardTimeSeriesTestSuiteConfig) create(t *testing.T, parent string) *TensorboardTimeSeries {
	t.Helper()
	created, err := fx.Service().CreateTensorboardTimeSeries(fx.Context(), &CreateTensorboardTimeSeriesRequest{
		Parent:                parent,
		TensorboardTimeSeries: fx.Create(parent),
	})
	assert.NilError(t, err)
	return created
}

func (fx *TensorboardServiceTensorboardTimeSeriesTestSuiteConfig) notFoundName(name string) string {
	// appending to the resource name ensures it is valid
	return name + "notfound"
}

func (fx *TensorboardServiceTensorboardTimeSeriesTestSuiteConfig) field(msg *TensorboardTimeSeries, name protoreflect.Name) *TensorboardTimeSeries {
	msg = fx.normalize(msg)
	fd := msg.ProtoReflect().Descriptor().Fields().ByName(name)
	only := &TensorboardTimeSeries{}
	if msg.ProtoReflect().Has(fd) {
		only.ProtoReflect().Set(fd, msg.ProtoReflect().Get(fd))
	}
	return only
}

func (fx *TensorboardServiceTensorboardTimeSeriesTestSuiteConfig) withoutField(msg *TensorboardTimeSeries, name protoreflect.Name) *TensorboardTimeSeries {
	cleared := proto.Clone(msg).(*TensorboardTimeSeries)
	cleared.ProtoReflect().Clear(cleared.ProtoReflect().Descriptor().Fields().ByName(name))
	return cleared
}
